\ResumeTitle


\section{教育经历}
\ResumeItem
[广东工业大学|本科]
{广东工业大学}
[信息与计算科学| 本科（2024.09—2028.09）]
[GPA：3.82/5.00]

\begin{itemize}[itemsep=0.1em]
  \item CET-4（580），CET-6（560）。
  \item \makebox[0.48\textwidth][l]{第 34 届全国大学生数学建模竞赛广东赛区一等奖。}• 第七届华数杯数学建模大赛全国三等奖。
  \item \makebox[0.48\textwidth][l]{第 18 届全国计算机能力挑战赛广东赛区一等奖。}• 第 17 届蓝桥杯 C++ 程序设计大赛一等奖。
  \item \makebox[0.48\textwidth][l]{广东工业大学数学建模大赛一等奖。}• 广东工业大学优秀学生奖学金。
\end{itemize}

\section{实习经历}
\ResumeItem
[影石创新股份有限公司|嵌入式软件实习生]
{影石创新股份有限公司}
[相机工程部 通信组| 嵌入式软件实习生]
[2026.03—2026.06]

\textbf{项目一：RTMP 直播推流服务开发}

项目简介：基于影石 Ace Pro 3 产品线，参与运动相机平台 AIPL 框架下的应用层独立直播进程的模块开发。

\begin{itemize}
  \item \textbf{参与直播进程业务接口开发}。通过 IBus 总线暴露 Prepare、Start、Stop 等核心接口，覆盖直播全生命周期管理；订阅 configd、netd、mediad 主题实现状态联动，基于共享内存同步直播状态，支撑 GUI 高频查询、规避 RPC 开销。
  \item \textbf{参与实现直播进程事件驱动状态机}。实现直播进程五态转换，通过基类默认事件处理拦截非法状态跳转请求；采用主线程接收通信回调、工作线程串行驱动状态机转换的双线程模型，保证并发场景下的状态一致性。
  \item \textbf{开发相机端命令行交互式维测工具}。集成 replxx 库支持自动补全与语法高亮，配合 adb shell 实现就地联调。
\end{itemize}

\textbf{项目二：基于 Ace Pro 2 机型的 AI 修图功能}

项目简介：在已上市的 Ace Pro 2 机型上开发相机 AI 修图功能，负责 App 与相机通信层、应用层开发。

\begin{itemize}
  \item \textbf{基于 UCD2.0 框架定义 AI 修图业务的 11 个命令码与 3 份 Protobuf 消息}，配合 CRC32 校验、分片确认与滑动窗口批量重传，闭环相机与手机 APP 的全链路通信。
  \item \textbf{参与相机与 APP 蓝牙通信链路的打通与传输速率优化}。基于博通协议栈，在内测版 BLE 基础上为 Android 端打通 SPP/RFCOMM 数据通路，测试得出流程耗时约 38s，提升约 35\%；针对 iOS 设备接入 L2CAP CoC 高吞吐数据通道。
  \item \textbf{实现相机端蓝牙唤醒 App 后台拉起}。当用户点击相机端 AI 修图入口时，Android 基于 Companion Device 机制触发 SPP 建链任务链；iOS 通过 iBeacon 广播唤醒 App 后建立 L2CAP CoC 通道。
\end{itemize}

\section{项目经历}

\ResumeItem[基于eBPF+DBus的多协议内核级网络质量监测平台]{\textbf{基于 eBPF+DBus 的}多协议内核级网络质量监测平台}[][][\textbf{技术栈}：C++11/17, eBPF/libbpf, DBus, pthread, netlink, glog, CMake, Python, sqlite\par\noindent\textbf{项目简介}：基于 D-Bus IPC 的网络质量监控服务，eBPF 内核级采集与多线程并发监控，集成 OpenSpec 开发工作流。]

\begin{itemize}
  \item \textbf{基于 eBPF 实现内核态多探针低开销采集}。实现流量速率、TCP 重传、HTTP 延迟等探针，经内核验证器校验后挂载至对应内核事件点完成采集；引入 CO-RE 机制消除对内核结构体布局的编译期依赖，兼容多内核版本。
  \item \textbf{基于 D-Bus 构建服务端与客户端通信架构}。多线程采集经互斥锁同步检测指标变更，服务类注册方法接口，事件经事件管理器集中分发，信号带重试同步发送避免阻塞采集；采样周期与探测目标可命令行热调整，无需重启服务。
  \item \textbf{设计端侧网络体验评估与根因诊断引擎}。按网络、服务、射频三层聚合九个评估维度，避免不同指标维度之间互相掩盖；内核采集丢失导致的超时证据降为未知而不误判，多故障同时命中时按因果关系区分根因与症状。
  \item \textbf{设计并落地基于 OpenSpec 规范的 AI 辅助开发工作流}。规划、实现与评估三阶段各设独立角色，规划阶段生成方案与任务文档并通过严格校验，实现阶段按测试驱动开发闭环执行任务，评估阶段独立核查测试驱动开发完整性与代码质量，验收通过后自动提交并归档。
\end{itemize}

\ResumeItem[基于ROS 2 Jazzy的仓储AMR调度基础设施平台]{\textbf{基于 ROS 2 Jazzy 的}仓储 AMR 调度基础设施平台}[][][\textbf{技术栈}：C++17, ROS 2 Jazzy, GoogleTest, CMake/colcon, Docker\par\noindent\textbf{项目简介}：基于 ROS 2 中间件的智能仓储 AMR 调度基础设施平台，多后端底盘通信容灾与分层故障注入验证流水线。]

\begin{itemize}
  \item \textbf{实现任务调度核心库与中间件解耦的任务调度框架}。将队列调度、拓扑寻路、死锁检测、资源预约与失败恢复决策抽离为纯 C++ 核心库，不依赖 ROS 组件；通过 BehaviorTree 驱动订单提交、出队派发与恢复策略编排。
  \item \textbf{构建多级安全熔断与通信容灾机制}。看门狗超时立即触发零速停车；通信链路以滑窗统计监控丢包率、CRC 错误与 RTT，丢包率超过 30\% 且经 30 秒冷却仍无改善则从串口降级到 UDP 再到本地模拟，恢复后自动回切。
  \item \textbf{设计 ROS 2 接口包暴露核心调度 Service}，覆盖任务入队/抢占/取消、交通封路与死锁检测、设施资源预约、运营快照聚合与配置校验；通过 REST Gateway 桥接 HTTP 请求与 ROS Service，实现外部业务系统接入。
  \item \textbf{搭建配置驱动的目录与业务工作流体系}。统一维护站点路网、设施、车队、业务类型、语义区五类 YAML 目录，支持跨目录引用校验；设施资源支持独占与会话管理，车队按能力标签与路线成本选车。
  \item \textbf{搭建分层自动化故障注入验证流水线}。串联单元测试、极限压测和三项故障演练，分别模拟死锁恢复、看门狗触发和通信降级场景；经测试，任务队列入队吞吐每秒 2.7 万次，异步日志入队吞吐每秒 228 万次。
\end{itemize}

\section{个人技能}

\begin{itemize}
  \item 熟悉 C++ 封装、继承、多态与 STL 常用容器，掌握 Lambda、智能指针等 C++11 特性，具备 Python 脚本能力。
  \item 熟悉进程/线程模型、IPC 与同步机制，理解零拷贝、线程池与死锁检测，掌握 socket 与 IO 多路复用编程。
  \item 掌握 TCP、UDP、DNS、ICMP、ARP 协议，理解三次握手、四次挥手、流量控制与拥塞控制机制。
  \item 熟悉 D-Bus 与 Protobuf 序列化，了解 BLE、SPP/RFCOMM、L2CAP 等经典蓝牙与低功耗蓝牙协议栈，了解 Wi-Fi 与 RTMP 流媒体协议。
  \item 熟悉 ROS 2 节点、话题、服务与生命周期模型，具备机器人中间件开发经验。
  \item 熟练使用 Git、GitLab CI/CD 与 Docker，能运用 Claude Code、Codex 等 AI 工具构建自动化开发工作流。
\end{itemize}

\end{document}

